// OpenFlow Controller Plugin - Flow-based networking via shared ingress + privacy chain
// Manages OpenFlow flows for the GhostBridge privacy tunnel (gbr_wg → gbr_warp → gbr_xray)
// and the shared gRPC bridge ingress port. No per-container sock_* ports.

use anyhow::{Context, Result, anyhow};
use async_trait::async_trait;
use log;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::PluginSchema;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::{OwnedValue as Value, json};
use std::collections::{BTreeMap, HashMap};
use zbus::proxy;

/// Proxy for the OpenFlow controller's dynamic flow-mod interface.
///
/// Served by the `op-of-controller` binary (crates/op-network/src/bin/op-of-controller.rs),
/// backed by `op_network::OpenFlowControllerHandle`. Replaces the old
/// `org.opdbus.rovs.openflow` passthrough, which was served solely by the
/// deprecated, now-removed `op-openvswitch-daemon` and never correctly
/// translated most of this plugin's match fields/actions (see git history of
/// that daemon's `parse_json_flow`).
#[proxy(
    default_service = "org.opdbus.v1.plugins.openflow",
    default_path = "/org/opdbus/v1/plugins/openflow",
    interface = "org.opdbus.v1.plugins.openflow"
)]
trait OpenFlowController {
    async fn send_flow(&self, flow_json: &str) -> zbus::Result<String>;
    async fn delete_flow(&self, flow_json: &str) -> zbus::Result<String>;
    async fn dump_flows(&self) -> zbus::Result<Vec<String>>;
    async fn ensure_fallback_normal(&self, bridge: &str) -> zbus::Result<String>;
    async fn set_fail_mode(&self, bridge: &str, mode: &str) -> zbus::Result<String>;
    async fn del_controller(&self, bridge: &str) -> zbus::Result<String>;
    async fn set_controller(&self, bridge: &str, endpoint: &str) -> zbus::Result<String>;
    async fn get_datapath_health(&self, bridge: &str) -> zbus::Result<String>;
    async fn attach_controller_safe(&self, bridge: &str, endpoint: &str) -> zbus::Result<String>;
}

/// OpenFlow controller configuration - Policy-based, not interface-based
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[schemars(extend("x-oscal-category" = "network"))]
pub struct OpenFlowConfig {
    /// Bridges managed by this controller
    pub bridges: Vec<BridgeFlowConfig>,

    /// Exact flow members confirmed by the native compare/exchange owner,
    /// keyed first by bridge and then by canonical flow identity. This is an
    /// observation tree; it never replaces the authored bridge configuration.
    #[serde(default)]
    #[schemars(extend("x-opdbus-exact-json-schema" = true))]
    pub observed_flows: BTreeMap<String, BTreeMap<String, FlowObservation>>,

    /// Controller endpoint (tcp:IP:PORT)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub controller_endpoint: Option<String>,

    /// Legacy discovery toggle retained for compatibility.
    #[serde(default)]
    pub auto_discover_containers: bool,

    /// Enable security hardening flows (default: true)
    #[serde(default = "default_security_enabled")]
    pub enable_security_flows: bool,

    /// Traffic obfuscation level for privacy (0=none, 1=basic, 2=pattern-hiding, 3=advanced)
    /// Level 1: Basic security (drop invalid, rate limit)
    /// Level 2: Pattern hiding (timing randomization, packet padding, TTL rewriting)
    /// Level 3: Advanced obfuscation (traffic morphing, protocol mimicry, decoy traffic)
    #[serde(default = "default_obfuscation_level")]
    pub obfuscation_level: u8,
}

/// One native observation, including confirmed absence after deletion.
/// Retaining the selector distinguishes an observed removal from unknown state.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct FlowObservation {
    pub flow: FlowEntry,
    pub installed: bool,
}

//! The EMQX doorbell: sled-gated, content-free wakes for private views.
//!
//! Owner decisions (2026-09-19): no broker ACL tables, no MCP over MQTT, no
//! authoritative state on the broker; SHM is the one truth. So the broker
//! carries exactly one thing per commit — `{"seq": <revision>}` on
//! `opdbus/wake/<owner-key>` — and every verdict here is a *function of the
//! identity the client presented*, never a lookup in a policy table:
//!
//! * A doorbell client's MQTT client id **is** its owner key
//!   (`sha256(principal, session, genesis)`, the same key the private
//!   episode view uses). The broker never sees a principal, session, or key.
//! * `client.authenticate`: the password is one of the door's two
//!   credentials — the inline SID1 (`sid1:…`, provisioned container/agent
//!   sessions) or the OIA1 assertion the decoy issued (`oia1:<base64>`, the
//!   browser). Each is verified exactly as the door verifies it (sled match
//!   with the `mqtt` transport scope, or signature/lifetime/replay/source
//!   binding plus the anchored human session), must belong to an unrevoked
//!   registered principal, and must derive exactly the client id.
//! * `client.authorize`: a doorbell client may only SUBSCRIBE to its own
//!   topic, and only while some anchored, unexpired sled still derives its
//!   client id (re-checked on every subscribe). Every other client is denied
//!   the `opdbus/` namespace and otherwise left to the broker's own rules.
//!
//! Revocation: tombstoning a sled makes the next subscribe fail, and the
//! bridge kicks the owner key's connection through `emqx.kick_client`.

use std::net::SocketAddr;

use base64::Engine as _;
use op_cozo_store::EpisodeScope;

use crate::mutation_engine::MutationEngine;
use crate::oracle_assertion::AssertionValidator;

/// Password prefix for an OIA1 assertion (standard base64 of the wire, as
/// the decoy issuer hands it to the browser).
pub(crate) const [REDACTED CREDENTIAL] &str = "oia1:";

/// Verdict for the broker: `Ignore` leaves the broker's own decision.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Verdict {
    Ignore,
    Allow,
    Deny,
}

/// Owner key for a verified scope — identical to the private view's key.
pub(crate) fn owner_key(scope: &EpisodeScope) -> String {
    crate::chatbot_episode_state::EpisodePublisher::key(scope)
}

/// Is this client id shaped like an owner key (and therefore a doorbell)?
pub(crate) fn is_doorbell_client(client_id: &str) -> bool {
    op_plugins::state_plugins::emqx::valid_owner_key(client_id)
}

fn scope_of(
    sled: &op_plugins::state_plugins::identity_sled::ContainerIdentitySled,
) -> Option<EpisodeScope> {
    Some(EpisodeScope {
        principal_id: op_identity::session::derive_principal_id(&sled.wireguard_pubkey),
        session_id: sled.session_id.clone(),
        session_genesis: sled.genesis.clone()?,
    })
}

/// `client.authenticate` for a doorbell client: the password is a door
/// credential and must derive exactly `client_id`.
pub(crate) async fn authenticate(
    engine: &MutationEngine,
    validator: &AssertionValidator,
    client_id: &str,
    password=***    peer: Option<SocketAddr>,
) -> Verdict {
    if !is_doorbell_client(client_id) {
        return Verdict::Ignore;
    }
    let outcome = if password.starts_with(op_identity::sealed_id::INLINE_PREFIX) {
        authenticate_sid1(engine, client_id, password).await
    } else if let Some(encoded) = password.strip_prefix([REDACTED CREDENTIAL]) {
        authenticate_oia1(engine, validator, client_id, encoded, peer).await
    } else {
…
