    fn grants() -> Grants {
        Grants {
            capabilities: vec![
                "cap.governance.schema-tag-registry.read@v1".into(),
                "cap.identity.sled.self.read@v1".into(),
                "cap.governance.routing-decision.read@v1".into(),
                "identity_sled.read".into(),
